## Write a function that checks a string for all unique characters.

### Response
function uniqueCharacters(string) { 

    let unique = true; 

    for (let i = 0; i < string.length; i++) { 
        for (let j = i + 1; j < string.length; j++) { 
            if (string[i] == string[j]) { 
                unique = false; 
            } 
        } 
    } 

    return unique; 
}

## Write a function to check if an integer is a prime number.

### Response
def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, n):
        if n % i == 0:
            return False
    return True

## Write a C code to evaluate a quadratic equation.

### Response
#include<stdio.h>
#include<math.h>

int main(){

	float a, b, c, x1, x2, imaginary, discriminant;
	printf("Enter the values of a, b, c : ");
	scanf("%f%f%f",&a,&b,&c);

	discriminant = (b*b) - (4*a*c);

	if (discriminant > 0)
	{
		//real and distinct roots
		x1 = (-b + sqrt(discriminant)) / (2*a);
		x2 = (-b - sqrt(discriminant)) / (2*a);
		printf("Real and distinct roots: %.2f and %.2f.", x1 , x2);
	}
	else if (discriminant == 0)
	{
		//real and equal roots
		x1 = x2 = -b / (2*a);
		printf("Real and Equal roots: %.2f and %.2f.", x1 , x2);
	}
	 else
